   "mainEntity": [
    {
     "@type": "Question",
     "name": "What is an ITIN number used for?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An ITIN is used to file US federal tax returns, claim treaty benefits and let US payers report income for people who cannot get an SSN. Typical UK users include property sellers, investors, beneficiaries of US estates and people claiming refunds of US tax withheld from winnings or pensions."
     }
    },
    {
     "@type": "Question",
     "name": "Is an ITIN the same as a Social Security Number?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An ITIN is not the same as a Social Security Number. An SSN is for people allowed to work in the US and links to social security benefits. An ITIN is only a tax processing number for people who are not eligible for an SSN, and it gives no right to work or benefits."
     }
    },
    {
     "@type": "Question",
     "name": "Can I get an ITIN if I live in the UK?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An ITIN can be issued to UK residents who have a US tax reason, such as filing a return or meeting an IRS exception. You do not need to visit the US. A Certifying Acceptance Agent in the UK can verify your passport so you do not post it to the IRS."
     }
    },
    {
     "@type": "Question",
     "name": "How long does an ITIN take?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An ITIN usually takes about 7 weeks after the IRS receives a complete application, or 9 to 11 weeks in peak season (15 January to 30 April) or from abroad, according to the IRS. In our experience, April to July can take 12 to 13 weeks, while applications from October often come back in 4 to 6 weeks. Errors add further delay."
     }
    },
    {
     "@type": "Question",
     "name": "Does an ITIN ever expire?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An ITIN expires if it is not used on a US federal tax return for three consecutive tax years. It lapses on 31 December of the third year. You renew with Form W-7 and a tax return, but only when you actually need to file."
     }
    },
    {
     "@type": "Question",
     "name": "Do I need an ITIN to fill in a W-8BEN?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An ITIN is not always needed for Form W-8BEN. Many UK residents can enter a UK tax number, such as a National Insurance number or UTR, to claim treaty rates. You usually need an ITIN when you must file a US return or a payer insists on one."
     }
    }
   ]
