  },
  {
   "@type": "FAQPage",
   "@id": "https://itinpro.uk/blog/irs-certifying-acceptance-agent-near-me-uk#faq",
   "mainEntity": [
    {
     "@type": "Question",
     "name": "Where can I find an IRS acceptance agent near me in the UK?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An IRS acceptance agent near you can be found in the IRS online directory of acceptance agents. ITIN Pro UK's Acceptance Agent agreement was approved in October 2026, started on 6 October 2026 and is valid until 2030; our directory listing is pending. We offer home visits around Bedford and Milton Keynes, office visits, and video interviews."
     }
    },
    {
     "@type": "Question",
     "name": "Do I have to send my passport to the IRS for an ITIN?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "Your passport does not have to go to the IRS if a Certifying Acceptance Agent verifies it. The CAA inspects the original, signs a certificate of accuracy and returns it to you. Without a CAA, you would normally post the original or an issuing-agency certified copy."
     }
    },
    {
     "@type": "Question",
     "name": "Can a solicitor certify my passport for an ITIN?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "A solicitor or notary-certified copy of your passport is not accepted for an ITIN. The IRS only accepts originals or copies certified by the agency that issued the document, such as HM Passport Office. A CAA can verify your original instead."
     }
    },
    {
     "@type": "Question",
     "name": "Can I do the ITIN ID check by video call?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "An ITIN ID check by video is allowed only if the CAA physically holds your original passport, or issuing-agency certified copy, during the call. For remote clients that means sending it by secure tracked courier first. A scan or video alone is not enough."
     }
    },
    {
     "@type": "Question",
     "name": "Can a CAA verify my children's documents?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "A CAA can verify a dependant's passport and birth certificate, but not other documents for children. If your child's application relies on something else, such as school or medical records, those may need to go directly to the IRS. Ask us before you book."
     }
    },
    {
