   "mainEntity": [
    {
     "@type": "Question",
     "name": "How do I know if my ITIN has expired?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "Your ITIN has expired if it wasn't used on a US federal tax return for three consecutive tax years. It lapses on 31 December of the third year. Check which years you last filed a return with it; if there's a three-year gap, assume renewal is needed."
     }
    },
    {
     "@type": "Question",
     "name": "Do I need to renew my ITIN if I'm not filing this year?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "No, you only need to renew an expired ITIN when you need to file a US federal tax return again. If you have no US income or refund to claim, you can leave it expired and renew later when a filing need comes up."
     }
    },
    {
     "@type": "Question",
     "name": "Do I get a new ITIN number when I renew?",
     "acceptedAnswer": {
      "@type": "Answer",
      "text": "No, an ITIN renewal usually reactivates your existing number. You enter your current ITIN on Form W-7 and tick 'Renew an existing ITIN'. If the IRS treats it as a new application by mistake, you could end up with confusing records, so tick the right box."
     }
